# Give a person an alias. A refused alias (no signed-in user, a blank alias, unknown person, an alias equal, as names
# are compared, to any name or alias on the sheet) writes nothing, not even an audit line.
validate:
  class: net.officefloor.hq.app.person.ValidateAlias
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SaveAlias
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonAliasAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
# Name another person on the sheet as a patron of this one. A refused patron (no signed-in user, unknown person
# or patron, the person themselves, one already named) writes nothing, not even an audit line.
validate:
  class: net.officefloor.hq.app.patron.ValidatePatron
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: refuse
refuse:
  class: net.officefloor.hq.app.patron.RefusePatron
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.patron.SavePatron
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.patron.AuditPatronAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.patron.RespondWithPatronCreated
  govern: [ transaction ]
# Retire a person from a date (blank: the sheet's today). A claim dated after it is then refused; from the day the
# sheet's today reaches it, their OPEN and PENDING claims not bound by a statement leave every live total (their
# SETTLED ones still count). A refused retire (no signed-in user, bad date, unknown person) writes nothing, not even an audit line.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SaveRetire
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonRetired
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditRetireRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user and an alias that is not blank. */
public class ValidateAlias {
    public void validate(@RequestBody AliasRequest request, Out<AliasInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before giving people aliases.");
        }
        String alias = request.alias() == null ? "" : request.alias().trim();
        if (alias.isEmpty()) {
            throw new InvalidPersonException("An alias is required.");
        }
        if (alias.length() > 200) {
            throw new InvalidPersonException("An alias must be at most 200 characters.");
        }
        body.set(new AliasInput(request.user().trim(), alias));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Give the loaded person the alias, refused when it equals, as names are compared, any name or alias on the sheet.
 *  Leaves the version alone: an alias is not an edit of the person. */
public class SaveAlias {
    public void save(@Val AliasInput input, @Val Person loaded, PersonRepository repository, Out<PersonResponse> saved)
            throws DuplicatePersonNameException {
        if (repository.nameInUse(loaded.sheetId(), input.alias(), null)) {
            throw new DuplicatePersonNameException(input.alias());
        }
        repository.alias(loaded, input.alias());
        saved.set(PersonResponse.from(repository.find(loaded.sheetId(), loaded.id())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the stored alias in the audit file. */
public class AuditPersonAliasAdded {
    public void audit(@Val AliasInput input, @Val Person loaded, Audit audit) {
        audit.record("PERSON_ALIAS_ADDED sheet=" + loaded.sheetId() + " by=" + input.user() + " name=" + loaded.name()
                + " alias=" + input.alias());
    }
}
package net.officefloor.hq.app.person;

/** A validated alias: the signed-in user, and the alias trimmed and not blank. */
public record AliasInput(String user, String alias) {
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/** A person on a sheet: a name and a grade (A, B or C: the one in force on the sheet's today), the version of the stored person, how many statements
 *  have been taken of them, and the last one's due-total (null when n/a, or none taken) and date (the sheet's
 *  today then; null when none taken), the date they are retired from (null: not retired), and whether they are
 *  dated grades and their dated holds (their OPEN claims dated within one, not bound by a statement, count in no
 *  live total), their own terms in days (null: none), their contact (trimmed, lower-cased; null: none), and their
 *  aliases, sorted as names are compared. */
public record Person(long id, String sheetId, String name, String grade, long version, int statementCount,
        BigDecimal statedTotal, LocalDate statementDate, LocalDate retiredFrom, Grades grades,
        Holds holds, Integer terms, String contact, List<String> aliases) {
}

