cd /home/daniel/ui-work/runs/202610221-to/sandbox/officehq-tanstack-officefloor; rm $TMPDIR/probe/probe.spec.ts; { echo "import { test, expect } from '@playwright/test';"; echo "import * as ui from './ui';"; echo "test.setTimeout(240_000);"; sed -n 6,142p e2e/specs/acceptance.spec.ts; } > $TMPDIR/probe/main.spec.ts
python3 - "$TMPDIR/probe/main.spec.ts" <<'EOF'
import sys
p=sys.argv[1]; s=open(p).read()
s=s.replace('''const c_benny_3 = ui.must(await ui.quickAdd(pg_vic, {"name": "benny", "amount": "1.00"}));''','''await pg_vic.getByTestId('quick-name').fill('benny');
    await pg_vic.getByTestId('quick-amount').fill('1.00');
    await pg_vic.getByTestId('quick-submit').click();
    await expect(ui.row(pg_vic, p_ada).locator('[data-testid^="claim-row-"]')).toHaveCount(4);
    const c_benny_3 = await ui.claimAt(pg_vic, p_ada, 3);''')
i=s.index('getByTestId("claim-row-" + c_benny_3).getByTestId("claim-amount")).toHaveText("20.00")')
s=s[:i]+s[i:].replace('c_benny_3','c_ada_1',2)
open(p,'w').write(s)
EOF
cd $TMPDIR/probe && BASE_URL=http://localhost:3000 AUDIT_FILE=/home/daniel/ui-work/runs/202610221-to/sandbox/officehq-tanstack-officefloor/.run/audit.log npx playwright test main.spec.ts --reporter=line 2>&1 | grep -v "^\s*$" | head -40

